// Decoration sprites (tree/bush/boulder/mountain-peak billboards) as raw
// RGBA pixel bytes (base64-encoded), NOT PNG files - same reasoning as
// terrainTiles.js: THREE.DataTexture built directly from these bytes,
// no image decode, so it works without a DOM/Image ('document').
// Each entry is { width, height, base64 } where base64 decodes to
// width*height*4 bytes, RGBA, row-major, top row first.

export const DECO_SPRITE_RAW = {
  tree: { width: 96, height: 96, base64: '' },
  bush: { width: 96, height: 96, base64: '' },
  boulder: { width: 96, height: 96, base64: '' },
  mountainPeak: { width: 96, height: 96, base64: '' },
};
